multi_head_attention:
batch, q_length, _ = x.shape
k_length = context.shape[1]
def project(tensor, name):
    y = linear(tensor, weights[prefix + name + ".weight"])
    return y.reshape(batch, tensor.shape[1], heads, -1).transpose(1, 2)
q, k, v = project(x, "q"), project(context, "k"), project(context, "v")
scores = q @ k.transpose(-1, -2)
if bias is not None:
    scores = scores + bias
scores = scores.masked_fill(~mask, torch.finfo(scores.dtype).min)
probabilities = torch.softmax(scores.float(), dim=-1).to(scores.dtype)
y = (probabilities @ v).transpose(1, 2).contiguous().reshape(batch, q_length, -1)
return linear(y, weights[prefix + "o.weight"])

decode_logits:
hidden = transformer_stack(decoder_ids, torch.ones_like(decoder_ids), weights, config,
